import os
import hashlib
from pathlib import Path
import json

def find_duplicates(directory: str, output_path: str) -> None:
    file_hashes = {}
    duplicates = []

    def hash_file(file_path):
        try:
            with open(file_path, 'rb') as f:
                return hashlib.sha256(f.read()).hexdigest()
        except Exception as e:
            print(f"warning: cannot read {file_path}: {e}", file=sys.stderr)
            return None

    for root, _, files in os.walk(directory):
        for file_name in files:
            file_path = Path(root) / file_name
            if file_path.is_file():
                file_hash = hash_file(file_path)
                if file_hash and file_hash != 'd41d8cd98f00b204e9800998ecf8427e':  # SHA-256 hash of an empty file
                    if file_hash in file_hashes:
                        file_hashes[file_hash].append(file_path)
                    else:
                        file_hashes[file_hash] = [file_path]

    for _, paths in file_hashes.items():
        if len(paths) > 1:
            duplicates.append(sorted(path.as_posix() for path in paths))

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(duplicates, f, indent=2)

# Example usage
# find_duplicates('/path/to/directory', '/path/to/output.json')
