import os
import hashlib
from pathlib import Path
import json

def find_duplicates(directory: str, output_path: str) -> None:
    def hash_file(file_path):
        if file_path.stat().st_size == 0:
            return None

        hasher = hashlib.sha256()
        try:
            with open(file_path, 'rb') as f:
                while chunk := f.read(4096):
                    hasher.update(chunk)
            return hasher.hexdigest()
        except Exception as e:
            print(f"warning: cannot read {file_path}: {e}", file=sys.stderr)
            return None

    def walk_directory(directory):
        file_hashes = {}
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = Path(root) / file
                file_hash = hash_file(file_path)
                if file_hash is not None:
                    if file_hash not in file_hashes:
                        file_hashes[file_hash] = []
                    file_hashes[file_hash].append(str(file_path))
        return file_hashes

    def filter_duplicate_groups(file_hashes):
        duplicate_groups = [files for files in file_hashes.values() if len(files) > 1]
        return sorted([sorted(group) for group in duplicate_groups])

    directory_path = Path(directory)
    file_hashes = walk_directory(directory)
    duplicate_groups = filter_duplicate_groups(file_hashes)

    with open(output_path, 'w') as output_file:
        json.dump(duplicate_groups, output_file, indent=4)

