        if len(paths) > 1:
            duplicates.append(sorted(Path(path).relative_to(directory).as_posix() for path in paths))

    # Sort the list of duplicate groups by their first path
    duplicates.sort(key=lambda x: x[0])

    # Write the JSON report to the output file
