import os
from pathlib import Path

def find_duplicates(directory: str, output_path: str) -> None:
    # Helper function to calculate SHA-256 hash of a file's content
    def file_hash(file_path):
        hasher = hashlib.sha256()
        try:
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    hasher.update(chunk)
            return hasher.hexdigest()
        except Exception as e:
            print(f"warning: cannot read {file_path}: {e}", file=sys.stderr)
            return None

    # Dictionary to store file hashes and their paths
    file_hashes = {}

    # Walk the directory tree
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            file_hash_value = file_hash(file_path)

            if file_hash_value is not None:
                if file_hash_value in file_hashes:
                    file_hashes[file_hash_value].append(file_path)
                else:
                    file_hashes[file_hash_value] = [file_path]

    # Filter out empty files and groups with only one file
    duplicate_groups = [
        paths for paths in file_hashes.values()
        if len(paths) > 1 and all(os.path.getsize(path) > 0 for path in paths)
    ]

    # Sort paths lexicographically and then sort groups by their first path
    sorted_duplicate_groups = [sorted(group) for group in duplicate_groups]
    sorted_duplicate_groups.sort(key=lambda x: x[0])

    # Write the JSON report to the output file
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(sorted_duplicate_groups, f, indent=4)

# Example usage (not part of the module)
if __name__ == "__main__":
    import sys
