import os
import hashlib
from pathlib import Path
import json

def find_duplicates(directory: str, output_path: str) -> None:
    file_hashes = {}
    duplicate_groups = []

    def hash_file(file_path):
        hasher = hashlib.sha256()
        try:
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hasher.update(chunk)
            return hasher.hexdigest()
        except Exception as e:
            print(f"warning: cannot read {file_path}: {e}", file=sys.stderr)
            return None

    def add_to_groups(file_hash, file_path):
        if file_hash in file_hashes:
            group = file_hashes[file_hash]
            if file_path not in group:
                group.append(file_path)
                if len(group) > 1:
                    duplicate_groups.append(sorted(group))
        else:
            file_hashes[file_hash] = [file_path]

    base = Path(directory)
    for root, _, files in os.walk(directory):
        for file_name in files:
            file_path = Path(root) / file_name
            if file_path.is_file() and not file_path.is_symlink():
                file_hash = hash_file(file_path)
                if file_hash is not None and int(file_path.stat().st_size) > 0:
                    add_to_groups(file_hash, str(file_path.relative_to(base).as_posix()))

    duplicate_groups.sort(key=lambda x: x[0])
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(duplicate_groups, f, indent=4)

